import{_ as n,a0 as r,w as s,s as h,ao as c,I as l,x as t,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Echo命令實例 | LCTT x X-CMD","titleTemplate":false,"description":"Echo命令實例 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Echo命令實例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Echo命令實例 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140811 Echo Command with Practical Examples","title":"Echo命令實例","tag":"201408","desc":""},"relativePath":"201408/20140811 Echo Command with Practical Examples.md","filePath":"[post].md"}'),p={name:"201408/20140811 Echo Command with Practical Examples.md"};function m(d,e,u,x,b,f){const i=r("Link");return s(),h("div",null,[e[11]||(e[11]=c(`<h1 id="echo命令實例" tabindex="-1">Echo命令實例 <a class="header-anchor" href="#echo命令實例" aria-label="Permalink to “Echo命令實例”">​</a></h1><p>echo命令是內建的<strong>shell命令</strong>，用於顯示<strong>變量</strong>的值或者<strong>打印一行文本</strong>。</p><p>echo命令在構建shell腳本時扮演着重要的角色。</p><h3 id="語法" tabindex="-1">語法： <a class="header-anchor" href="#語法" aria-label="Permalink to “語法：”">​</a></h3><pre><code># echo [Options] [String]
</code></pre><p>方括號中的項目是可選的。字符串可以定義為字符的有限序列（如字母，數字，符號，標點符號）。</p><p>當echo命令不帶任何選項或字符串使用時，它會在顯示屏上返回一個空白行，後面換一行跟上命令提示符。這是因為按下回車鍵就是發送一個信號給系統以開始一個新行，而echo重複了該信號。</p><h3 id="選項" tabindex="-1">選項： <a class="header-anchor" href="#選項" aria-label="Permalink to “選項：”">​</a></h3><ul><li>-n 不要輸出衍生的新行</li><li>-e 啓用反斜線轉義解釋</li><li>-E 禁用反斜線轉義解釋（默認）</li></ul><p>如果使用-e選項，則可以使用如下轉義序列：</p><ul><li>\\ 反斜線</li><li>\\a 警告（BEL）</li><li>\\b 反斜線</li><li>\\c 不產生進一步輸出</li><li>\\e 轉義</li><li>\\f 換頁</li><li>\\n 新行</li><li>\\r 換行字符</li><li>\\t 水平製表</li><li>\\v 垂直製表</li><li>\\0NNN 八進制值表示的字節NNN（1到3個數字）</li><li>\\xHH 十六進制值表示的字節NNN（1到2個數字）</li></ul><h3 id="樣例-1-顯示系統定義的變量的值" tabindex="-1">樣例：1 顯示系統定義的變量的值 <a class="header-anchor" href="#樣例-1-顯示系統定義的變量的值" aria-label="Permalink to “樣例：1  顯示系統定義的變量的值”">​</a></h3><p>使用set命令，我們可以列出系統定義的變量。而要打印這些變量的值，我們可以使用echo命令：</p><pre><code>jack@localhost:~$ echo $USER
jack
jack@localhost:~$ echo $HOME
/home/jack
</code></pre><h3 id="樣例-2-顯示用户定義的變量的值" tabindex="-1">樣例：2 顯示用户定義的變量的值 <a class="header-anchor" href="#樣例-2-顯示用户定義的變量的值" aria-label="Permalink to “樣例：2 顯示用户定義的變量的值”">​</a></h3><pre><code>jack@nextstep4it:~$ var1=\`date\`
jack@nextstep4it:~$ echo &quot;Today&#39;s date  time is : $var1&quot;
Today&#39;s date  time is : Mon Jul 28 13:11:37 IST 2014
</code></pre><h3 id="樣例-3-顯示文本字符串" tabindex="-1">樣例：3 顯示文本字符串 <a class="header-anchor" href="#樣例-3-顯示文本字符串" aria-label="Permalink to “樣例：3 顯示文本字符串”">​</a></h3><pre><code>jack@nextstep4it:~$ echo &quot; Hi this echo command testing&quot;
Hi this echo command testing
</code></pre><h3 id="樣例-4-在echo命令中使用反斜線" tabindex="-1">樣例：4 在echo命令中使用反斜線 <a class="header-anchor" href="#樣例-4-在echo命令中使用反斜線" aria-label="Permalink to “樣例：4 在echo命令中使用反斜線”">​</a></h3><pre><code>jack@nextstep4it:~$ echo -e &quot;Ubuntu \\bis \\bthe \\bbest \\bDesktop \\bOS&quot;
</code></pre><p>上述命令將打印：</p><p>UbuntuisthebestDesktopOS</p><h3 id="樣例-5-在echo命令中使用製表符空格" tabindex="-1">樣例：5 在echo命令中使用製表符空格 <a class="header-anchor" href="#樣例-5-在echo命令中使用製表符空格" aria-label="Permalink to “樣例：5  在echo命令中使用製表符空格”">​</a></h3><pre><code>nextstep4it@nextstep4it:~$ echo -e &quot;Ubuntu \\tis \\tthe \\tbest \\tDesktop \\tOS&quot;
</code></pre><p>上述命令將顯示如下輸出：</p><p>Ubuntu is the best Desktop OS</p><h3 id="樣例-6-在echo命令中使用垂直製表符" tabindex="-1">樣例：6 在echo命令中使用垂直製表符 <a class="header-anchor" href="#樣例-6-在echo命令中使用垂直製表符" aria-label="Permalink to “樣例：6 在echo命令中使用垂直製表符”">​</a></h3><pre><code>jack@nextstep4it:~$ echo -e &quot;Ubuntu \\vis \\vthe \\vbest \\vDesktop \\vOS&quot;
Ubuntu
       is
              the
                     best
                            Desktop
                                          OS
</code></pre><h3 id="樣例-7-設置echo命令彩色輸出" tabindex="-1">樣例：7 設置echo命令彩色輸出 <a class="header-anchor" href="#樣例-7-設置echo命令彩色輸出" aria-label="Permalink to “樣例：7  設置echo命令彩色輸出”">​</a></h3><p>echo命令可以修改字體類型，字體背景色以及字體顏色，轉義序列\\033可以用於改變字體屬性。要使轉義序列生效，必須使用-e選項。下面列出了部分轉義代碼：</p><ul><li>[0m: 正常</li><li>[1m: 粗體</li><li>[4m: 字體加上下劃線</li><li>[7m: 逆轉前景和背景色</li><li>[8m: 不可見字符</li><li>[9m: 跨行字體</li><li>[30m: 灰色字體</li><li>[31m: 紅色字體</li><li>[32m: 綠色字體</li><li>[33m: 棕色字體</li><li>[34m: 藍色字體</li><li>[35m: 紫色字體</li><li>[36m: 淺藍色字體</li><li>[37m: 淺灰字體</li><li>[38m: 黑色字體</li><li>[40m: 黑色背景</li><li>[41m: 紅色背景</li><li>[42m: 綠色背景</li><li>[43m: 棕色背景</li><li>[44m: 藍色背景</li><li>[45m: 紫色背景</li><li>[46m: 淺藍色背景</li><li>[47m: 淺灰色背景</li></ul><p>下面的命令將用紅色打印輸出。</p><pre><code>jack@nextstep4it:~$ echo -e &quot;\\033[31mMagic of Linux\\033[0m&quot;
Magic of Linux
</code></pre><p>下面的命令將以粗體以及紅色背景打印出“Magic of Linux”。</p><pre><code>nextstep4it@nextstep4it:~$ echo -e &quot;\\033[1m\\033[41mMagic of Linux\\033[0m&quot;
Magic of Linux
</code></pre><hr>`,36)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),a(i,{href:"http://www.nextstep4it.com/categories/unix-command/echo-command/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.nextstep4it.com/categories/unix-command/echo-command/",-1)])]),_:1})]),l("p",null,[e[4]||(e[4]=t("譯者：",-1)),a(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...e[2]||(e[2]=[t("GOLinux",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[8]||(e[8]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),a(i,{href:"http://linux.cn/"},{default:o(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const E=n(p,[["render",m]]);export{g as __pageData,E as default};
